source("pre.R")
tohex <- function(l) vapply(l, function(b) if (is.null(b)) "NA" else paste0("E", paste(sprintf("%02x", as.integer(b)), collapse="")), "")
unhex <- function(h) vapply(h, function(z) { if (!nzchar(z)) return(""); r <- as.raw(strtoi(substring(z, seq(1,nchar(z),2), seq(2,nchar(z),2)), 16L)); rawToChar(r) }, "", USE.NAMES=FALSE)
d <- read.delim("cases8.tsv", header=FALSE, col.names=c("hex","ref"), colClasses="character", na.strings=character(), quote="")
d$text <- unhex(d$hex); got <- tohex(id_decode(d$text, "words"))
cat("words:", nrow(d), "cases", sum(d$ref!="NA"), "ref-valid", sum(got!=d$ref), "disagreements\n")
u <- d[got!=d$ref,]; print(table(ifelse(u$ref=="NA","zuid-accepts","other"))); print(substr(head(u$text[u$ref=="NA"],3),1,80)); print(substr(head(u$text[u$ref!="NA"],3),1,80))
w <- readLines("words_all.txt"); mine <- id_encode(lapply(0:65535, function(i) as.raw(c(i %/% 256, i %% 256))), "words")
cat("word list mismatches:", sum(w != mine), " shortest:", min(nchar(w)), " longest:", max(nchar(w)), "\n")
q <- read.delim("cases9.tsv", header=FALSE, col.names=c("text","ref"), colClasses="character")
cat("proquint mismatches:", sum(tohex(id_decode(q$text, "proquint")) != paste0("E", q$ref)), " enc mismatches:", sum(id_encode(lapply(q$ref, function(h) as.raw(strtoi(substring(h, c(1,3,5,7), c(2,4,6,8)), 16L))), "proquint") != q$text), "\n")
p(id_decode(c("lusab-babad", "LUSAB BABAD", "lusabbabad", "lusab--babad", "lusa-bbabad", "lusab-baba", "lusab–babad", "luséab-babad", "lusab-babad\n", "1lusab"), "proquint"))
p(id_decode(c("a–a", "é"), "words"))
x <- id_parse("f81d4fae-7dec-11d0-a765-00a0c91e6bf6", "uuid")
pq <- id_format(x, "proquint"); wd <- id_format(x, "words")
p(id_parse(c(pq, toupper(pq), gsub("-", " ", pq), gsub("-", "–", pq), gsub("-", "", pq)), "uuid", form="proquint"))
p(id_parse(c(wd, toupper(wd), gsub("-", " ", wd), gsub("-", "–", wd)), "uuid", form="words"))
